import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { collection, getDocs, addDoc, deleteDoc, doc } from "firebase/firestore";
import { db } from "../services/firebaseConfig";

export default function Transactions() {
  const [transactions, setTransactions] = useState([]);
  const [categories, setCategories] = useState([]);
  const [newTransaction, setNewTransaction] = useState({ type: "Saída", category: "", value: "", customCategory: "", date: "" });
  const [isAdding, setIsAdding] = useState(false);
  const [isClearing, setIsClearing] = useState(false);

  const fetchTransactions = async () => {
    const querySnapshot = await getDocs(collection(db, "transactions"));
    setTransactions(querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
  };

  const fetchCategories = async () => {
    const querySnapshot = await getDocs(collection(db, "categories"));
    setCategories(querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
  };

  useEffect(() => {
    fetchTransactions();
    fetchCategories();
  }, []);

  const handleAddTransaction = async () => {
    const categoryToSave = newTransaction.category === "Outra" ? newTransaction.customCategory : newTransaction.category;
    if (!categoryToSave || !newTransaction.value) {
      alert("Preencha todos os campos!");
      return;
    }
    setIsAdding(true);
    try {
      await addDoc(collection(db, "transactions"), {
        ...newTransaction,
        category: categoryToSave,
        value: parseFloat(newTransaction.value),
        date: newTransaction.date || new Date().toISOString().split("T")[0]
      });
      setNewTransaction({ type: "Saída", category: "", value: "", customCategory: "", date: "" });
      fetchTransactions();
    } catch (error) {
      console.error("Erro ao adicionar transação:", error);
      alert("Erro ao adicionar transação. Tente novamente.");
    } finally {
      setIsAdding(false);
    }
  };

  const handleClearTransactions = async () => {
    if (!window.confirm("Tem certeza que quer apagar todas as transações? Esta ação não pode ser desfeita!")) return;
    setIsClearing(true);
    try {
      const querySnapshot = await getDocs(collection(db, "transactions"));
      const deletePromises = querySnapshot.docs.map(document =>
        deleteDoc(doc(db, "transactions", document.id))
      );
      await Promise.all(deletePromises);
      fetchTransactions();
    } catch (error) {
      console.error("Erro ao limpar transações:", error);
      alert("Erro ao limpar transações. Tente novamente.");
    } finally {
      setIsClearing(false);
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return "Sem data";
    const date = new Date(dateString);
    return date.toLocaleDateString('pt-BR');
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
      className="p-6 max-w-6xl mx-auto"
    >
      <motion.div
        initial={{ opacity: 0, x: -20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ delay: 0.2 }}
        className="mb-8"
      >
        <h1 className="text-3xl font-bold text-white mb-2">💳 Gerenciar Transações</h1>
        <p className="text-gray-400">Adicione e visualize suas entradas e saídas financeiras</p>
      </motion.div>

      {/* Formulário de Adição */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
        className="bg-gradient-to-br from-gray-800 to-gray-900 p-6 rounded-xl shadow-xl border border-gray-700/50 mb-8"
      >
        <h2 className="text-xl font-semibold text-white mb-4">➕ Nova Transação</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">
              Tipo
            </label>
            <div className="relative">
              <select
                value={newTransaction.type}
                onChange={(e) => setNewTransaction({ ...newTransaction, type: e.target.value })}
                className="w-full px-4 py-3 bg-gradient-to-r from-gray-700 to-gray-800 border border-gray-600 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 appearance-none cursor-pointer pr-10"
                style={{
                  backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236b7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='m6 8 4 4 4-4'/%3e%3c/svg%3e")`,
                  backgroundPosition: 'right 0.5rem center',
                  backgroundRepeat: 'no-repeat',
                  backgroundSize: '1.5em 1.5em'
                }}
              >
                <option value="Entrada">💰 Entrada</option>
                <option value="Saída">💸 Saída</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">
              Categoria
            </label>
            <div className="relative">
              <select
                value={newTransaction.category}
                onChange={(e) => setNewTransaction({ ...newTransaction, category: e.target.value })}
                className="w-full px-4 py-3 bg-gradient-to-r from-gray-700 to-gray-800 border border-gray-600 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 appearance-none cursor-pointer pr-10"
                style={{
                  backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236b7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='m6 8 4 4 4-4'/%3e%3c/svg%3e")`,
                  backgroundPosition: 'right 0.5rem center',
                  backgroundRepeat: 'no-repeat',
                  backgroundSize: '1.5em 1.5em'
                }}
              >
                <option value="">Selecione uma categoria...</option>
                {categories.map(cat => (
                  <option key={cat.id} value={cat.name}>
                    ● {cat.name}
                  </option>
                ))}
                <option value="Outra">➕ Criar nova categoria</option>
              </select>
            </div>
          </div>

          {newTransaction.category === "Outra" && (
            <div>
              <label className="block text-sm font-medium text-gray-300 mb-2">
                Nova Categoria
              </label>
              <input
                type="text"
                placeholder="Digite a categoria"
                value={newTransaction.customCategory}
                onChange={(e) => setNewTransaction({ ...newTransaction, customCategory: e.target.value })}
                className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
              />
            </div>
          )}

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">
              Valor (R$)
            </label>
            <input
              type="number"
              placeholder="0,00"
              step="0.01"
              min="0"
              value={newTransaction.value}
              onChange={(e) => setNewTransaction({ ...newTransaction, value: e.target.value })}
              className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
              onKeyPress={(e) => e.key === 'Enter' && handleAddTransaction()}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">
              Data
            </label>
            <input
              type="date"
              value={newTransaction.date}
              onChange={(e) => setNewTransaction({ ...newTransaction, date: e.target.value })}
              className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
            />
          </div>
        </div>

        <div className="flex gap-4 mt-6">
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={handleAddTransaction}
            disabled={isAdding}
            className="px-6 py-3 bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 text-white font-medium rounded-lg shadow-lg transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isAdding ? "Adicionando..." : "➕ Adicionar Transação"}
          </motion.button>

          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={handleClearTransactions}
            disabled={isClearing}
            className="px-6 py-3 bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-medium rounded-lg shadow-lg transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isClearing ? "Limpando..." : "🗑️ Limpar Todas"}
          </motion.button>
        </div>
      </motion.div>

      {/* Lista de Transações */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.6 }}
      >
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-semibold text-white">📋 Histórico de Transações</h2>
          <span className="text-gray-400 text-sm">{transactions.length} transações</span>
        </div>

        {transactions.length === 0 ? (
          <div className="bg-gray-800/50 p-12 rounded-xl text-center">
            <div className="text-6xl mb-4">📊</div>
            <p className="text-gray-400 text-lg">Nenhuma transação registrada ainda.</p>
            <p className="text-gray-500 text-sm mt-2">Adicione sua primeira transação acima!</p>
          </div>
        ) : (
          <div className="space-y-3">
            {transactions
              .sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0))
              .map((t, index) => (
                <motion.div
                  key={t.id}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.1 * index }}
                  whileHover={{ scale: 1.02 }}
                  className={`p-4 rounded-xl shadow-lg border transition-all duration-200 ${t.type === "Entrada"
                    ? "bg-gradient-to-r from-green-900/50 to-green-800/50 border-green-500/30"
                    : "bg-gradient-to-r from-red-900/50 to-red-800/50 border-red-500/30"
                    }`}
                >
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className={`text-2xl ${t.type === "Entrada" ? "text-green-400" : "text-red-400"}`}>
                        {t.type === "Entrada" ? "💰" : "💸"}
                      </div>
                      <div>
                        <div className="text-white font-medium">{t.category || "Sem categoria"}</div>
                        <div className="text-gray-400 text-sm">{formatDate(t.date)}</div>
                      </div>
                    </div>
                    <div className={`text-xl font-bold ${t.type === "Entrada" ? "text-green-400" : "text-red-400"}`}>
                      {t.type === "Entrada" ? "+" : "-"}{formatCurrency(t.value)}
                    </div>
                  </div>
                </motion.div>
              ))}
          </div>
        )}
      </motion.div>
    </motion.div>
  );
}
